import { TiledParser } from "./index2.js";
import { prepareTiledPhysicsData } from "./index4.js";
import client_default from "./index5.js";
import __ce_component from "./index6.js";
import { applyTiledMapStreamChunk, createTiledMapStreamState, removeTiledMapStreamChunk } from "./index7.js";
import { provideClientMapStreaming } from "@rpgjs/client";
//#region src/client-provider.ts
async function loadDirectTiledMap(map, options) {
	const response = await fetch(`${options.basePath}/${map}.tmx`);
	if (!response.ok) throw new Error(`Unable to load Tiled map '${map}': ${response.status} ${response.statusText}`);
	const mapData = await response.text();
	const parsedMap = new TiledParser(mapData).parseMap();
	const tilesets = [];
	for (const tileset of parsedMap.tilesets) {
		const tilesetResponse = await fetch(`${options.basePath}/${tileset.source}`);
		if (!tilesetResponse.ok) throw new Error(`Unable to load Tiled tileset '${tileset.source}': ${tilesetResponse.status} ${tilesetResponse.statusText}`);
		const parsedTileset = new TiledParser(await tilesetResponse.text()).parseTileset();
		parsedTileset.image.source = `${options.basePath}/${parsedTileset.image.source}`;
		tilesets.push({
			...tileset,
			...parsedTileset
		});
	}
	parsedMap.tilesets = tilesets;
	const mapObject = {
		data: mapData,
		component: __ce_component,
		parsedMap,
		id: map,
		params: { basePath: options.basePath }
	};
	prepareTiledPhysicsData(mapObject, mapObject);
	await options.onLoadMap?.(map);
	return mapObject;
}
function createTiledMapClientProviders(options) {
	return {
		client: client_default,
		providers: [...provideClientMapStreaming({
			adapter: {
				component: __ce_component,
				createState: createTiledMapStreamState,
				applyChunk: applyTiledMapStreamChunk,
				removeChunk: removeTiledMapStreamChunk,
				getData: (state) => state.parsedMap,
				getParams: (manifest) => ({ basePath: manifest.renderData.basePath })
			},
			directLoad: (map) => loadDirectTiledMap(map, options)
		})]
	};
}
//#endregion
export { createTiledMapClientProviders };
